quests[75154] = { id = 75154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Morqut Islet", description = "We have access tae The Forbidden Reach now, and Cataloger Daela is already waitin' fer ya there. \n\nShe's sent me a word of a very promising spire not far from the village where she's stayin'. \n\nThink there might be another dormant Waygate around? Go on an' find out!", progress = "Found anythin'?", completion = "I knew it!", objectives = "Locate the Dormant Waygate on the Morqut Islet in The Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
