quests[75168] = { id = 75168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Air Control", description = "We will never make progress while those shadowflame drakes have us pinned down from the air.\n\nGet up there and knock them from the skies.", progress = "They are not the only ones who can fly.", completion = "The skies are clearer already.", objectives = "Slay or knock Primal Nightflames from the air with Whirling Surge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
