quests[75181] = { id = 75181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volunteer Fire Fighters", description = "We must contain the fires these rituals are causing.\n\nWe are too far from the river to take advantage of the waters there but luckily we have two... volunteers... from beyond the plains that claim they can help. They need another pair of hands.\n\nPlease go find the goblin and gnome. I appreciate their help but they need a third party to direct them.", progress = "Quickly, before they spread.", completion = "A useful trick, to be sure. Now if those two would just see more eye to eye.", objectives = "Use the Water Elemental to diffuse fires in the Suffusion Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75182] = { id = 75182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Mammoth", description = "The djaradin have loaded a mammoth with the spoils of their labor here for delivery to Fyrakk.\n\nRedirect that shipment. We can make use of whatever supplies they've gathered.", progress = "It should be hard to miss. They are quite large, after all.", completion = "Excellent, this should put a mammoth dent in their operations.", objectives = "Mount an Overladen Mammoth and return it to your lines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75185] = { id = 75185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75189] = { id = 75189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "It is time we joined with the other survivors. The others mentioned that King Greymane and his royal guard are just south of here.", completion = "You've done well in coming here. If we Gilneans stick together, we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75190] = { id = 75190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready and Abel", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me. Someone was asking about you. A monk, Todd Abel, said he needed to speak with you. He seemed very concerned.", completion = "Glad to see you made it here safely.", objectives = "Speak to Todd Abel in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75200] = { id = 75200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepflayer Slayer" }
quests[75203] = { id = 75203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absent Friends", description = "I am concerned about our queen.\n\nAlexstrasza left to gather her thoughts some time ago and has not yet returned. I have no real cause for concern, but with all that has happened, I cannot help but fear for her well-being.\n\nPlease ease an old dragon's mind and ensure she is alright.", objectives = "Check on Alexstrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75212] = { id = 75212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
