quests[75286] = { id = 75286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmith's Back", description = "The kith of Loamm request the skills of a seasoned blacksmith! We've heard of the wonders you uplanders make with smelted ore!\n\nOur Kilnmaster, Mister Crubus, has heard you have devised a way to dig without claws or earth magic! What a wonderful invention!\n\nPlease deliver some of these \"shovels\" as soon as you can, won't you?", progress = "Who are you? Oh, Kayann sent you?\n\nWell, do you have what I asked for or what?", completion = "So these are those... What did you call them? Shovels?\n\nAnd you hold them in your hands, and move dirt with them? Huh.\n\nI'll be honest with you, friend. I'm an old niffen. I'm hoping these will spare me from bending over so much.\n\nWell, here goes nothing!", objectives = "Deliver Sturdy Expedition Shovels to Kilnmaster Crubus in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75288] = { id = 75288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Tales with Topuiz", description = "The kith of Loamm request the skills of an excellent enchanter! Magic is so prevalent in this wondrous city, it practically floats about on the breeze!\n\nOur chief Dustmonger and Sparklefinger, Mister Topuiz, has heard of the many different ways you enchant your clothes on the surface, and wishes to see some examples for himself!\n\nPlease deliver those scrolls as soon as you can, won't you?", progress = "Greetings, friend! You smell new!\n\nWhat brings you to the Dustmonger?", completion = "Oh, the scrolls I requested from Kayann! Lovely!\n\nMmm, smells like magic! Let's see if I can put these to good use!", objectives = "Deliver scrolls of Enchant Cloak - Writ of Leech, Enchant Cloak - Writ of Speed, and Enchant Cloak - Writ of Avoidance to Dustmonger Topuiz in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75289] = { id = 75289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ink Master", description = "The kith of Loamm request the skills of a scribe! We niffen have heard of the powerful magical writings you produce on the surface, and wish to smell your handiwork with our own noses!\n\nOur Chief Chiseler, Miss Scridorsa, has requested a sample of both pigment and runestone be brought below.\n\nMake a delivery to Loamm as soon as you can, won't you?", progress = "Hmm? Can I help you?\n\nI'm very busy, you know!", completion = "What's this? Why are you handing this to me?\n\n...\n\nOH! These are the items I requested from Kayann! Why didn't you say so?", objectives = "Deliver Shimmering Pigments and Chilled Runes to Scridorsa the Chiseler in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75290] = { id = 75290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Loamm Niffen", description = "Well hey there!\n\nWe want to thank you for all your help. How about you meet me in Loamm, so we get you something nice?\n\nKeep up the good work!", completion = "You're doing great! Thanks for all your help--we appreciate it!\n\nHopefully this'll be useful for you!", objectives = "Speak with Mimuup  in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75291] = { id = 75291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
