quests[75301] = { id = 75301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistie's Mix Magic", description = "The kith of Loamm request the skills of an alchemist! We have heard tales of the wondrous concoctions you uplanders have devised!\n\nWe have alchemists of our own down below! Miss Mistie has requested a few of these items.\n\nMake a delivery to Loamm as soon as you can, won't you?", progress = "Did Kayann send you? Do you have what I asked for?", completion = "Ah, so you're an alchemist then? Let me see those!\n\nVery good, very good! Stand back, while I work my magic!", objectives = "Deliver Aerated Mana Potions and Omnium Draconis to Mistie in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75304] = { id = 75304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Need... a Tailor", description = "The kith of Loamm request the skills of a talented tailor! We niffen are terribly curious about the magical finery you create here!\n\nWe have our own stitchers and clothes-makers down below. Mister Rossmar has expressed an interest in the procurement of bolts of high quality cloth!\n\nMake a delivery to Loamm as soon as you can, won't you?", progress = "Did Kayann send you? Oh, thank the soil!\n\nI need those bolts of cloth, and quickly!", completion = "Ohhh, this is wonderful cloth! It glides so gently through my claws, but also feel strong enough to withstand daily use! \n\nAnd you delivered it just in time! What's the emergency? Well...", objectives = "Deliver Vibrant Wildercloth Bolts to Rossmar in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75305] = { id = 75305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: Zaralek Cavern", description = "Zaralek Cavern is down under the Dragon Isle. Go and explore and see what you may dig up, but beware of foes who may get in your way!", progress = "Now, go out there.", completion = "Well done!", objectives = "Collect 100 Sparks of Life in Zaralek Cavern, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75307] = { id = 75307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Road to Season City", description = "The kith of Loamm request the skills of a culinary chef! We niffen are very proud of our cuisine, and wish to sample some from the surface!\n\nOne of our best cooks, Mister Phiary, has heard of the potent spices found in the food of the Maruuk Centaur, and the complex flavors found in the food of the Iskaara Tuskarr, and wishes to try these for himself!\n\nPlease deliver these to Loamm as soon as you can, won't you?", progress = "Hey, hey! You should stand back, it's about to get SPICY in here!", completion = "Oh, OH! That smell! New and funkalicious!\n\nYou must have that chow I asked for! Let's give it a spin!", objectives = "Deliver Yusa's Hearty Stews and Grand Banquets of the Kalu'ak to Phiary in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75308] = { id = 75308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrybbil Engineering", description = "The kith of Loamm request the skills of an engineer! We have heard of the marvelous machines invented right here in this city, and eagerly wish to put these to use underground!\n\nWe have an engineer of our own down below, Mister Scrybbil, who has a special interest in what you call \"fishing rods\". How does such a thing work? Do you use them to spear the fish? How strange!\n\nPlease deliver these \"fishing rods\" as soon as you can, won't you?", progress = "Step right up, and witness the fantastic inventions of Scrybbil! Can I interest you in a firework, sir and/or ma'am?\n\nWhat's that? You have a delivery for me?", completion = "Oh, wonderful! I've been waiting for this day!\n\nDown here, we just use our claws to catch fish. It's a bit barbaric and not really efficient! Now I can use this and catch a mountain of fish!\n\n... How does it work?", objectives = "Deliver Draconium Fisherfriends to Scrybbil in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75309] = { id = 75309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If a Gem Isn't Pretty", description = "The kith of Loamm request the skills of a jewelcrafter! I have seen the wondrous sparkling gems in this glorious city, and the niffen below wish to see them as well. We don't see very well, so we know the value of a good sparkle!\n\nOur chief Gemfinder and Jewelshiner, Miss Fanilly, wishes to see some beautiful gems. I bet she'd love the ones named after Alexstrasza and Ysera!\n\nPlease deliver them to Loamm as soon as you can, won't you?", progress = "Hello, hello! Did Kayann send you? \n\nI'm eager to get my hands on those gems!", completion = "Oh, are these the gems? Hmmm... I have to admit, I was expecting them to be prettier!\n\nI suppose they just need a bit of elbow grease and a spit shine! Watch this!", objectives = "Deliver Silken Gemdusts, Alexstraszites and Ysemeralds to Fanilly in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
