quests[75350] = { id = 75350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niffen Nabber" }
quests[75351] = { id = 75351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep a Leather Eye Open", description = "The kith of Loamm request the skills of a leatherworker! We've heard of the wonders you uplanders make with hides and scales!\n\nWe have leatherworkers of our own down below! Miss Garram has heard there's a set of magical drums that make you faster! Is such a thing possible?\n\nMake a delivery to Loamm as soon as you can, won't you?", progress = "Did Kayann send you? Do you have what I asked for?", completion = "Aha! So these are the hastening drums? I'm hoping these will help me move faster and get more work done each day.\n\nWe niffen have drums of our own, but nothing like these! Let's try them out!", objectives = "Deliver Feral Hide Drums to Garamm in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75352] = { id = 75352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75353] = { id = 75353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinn" }
quests[75354] = { id = 75354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mycelium Mastery", description = "Hey there, stranger! I had an idea to run by you.\n\nThe mushrooms that grow down in Zaralek Cavern have thick and powerful mycelium capable of gripping into even the hardest crystals.\n\nImagine the possibilities with such a material! I had a friend down in Loamm who was trying to work out how to make it into a leather!\n\nInterested? Bring my friend Garram some mushrooms!", progress = "We call those crystal clinging mushrooms Nightlight Conkerbells. Not only do they give off light, they even have a strong enough scent to help guide our noses!", completion = "What? There's hardly any mycelium on these!\n\n<Garram thinks.>\n\nI wonder... do they leave it behind in the crystal? \n\nHmm... I'll try to grow more here and experiment. Thanks for the help!", objectives = "Collect 10 Nightlight Conkerbell Samples and deliver them to Garram in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
