quests[75361] = { id = 75361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75362] = { id = 75362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cephalo-crystalization", description = "Well, hello there!\n\nHave you seen those snails in Zaralek Cavern with the crystals growing from their shells? \n\nWhen crushed to powder and mixed with a proper solution of slime, those crystals make a paste that adds a considerable luster to our gems! Bring some to my good friend Fanilly, and I'm sure she'll be happy to chat your ear off about jewelcrafting!", progress = "You know, a good shine on a gemstone is very important to us... we have such a hard time seeing it otherwise!", completion = "Oh yes, this will do! Now watch, just grind it together, then apply it to the gem and polish...", objectives = "Collect 10 Whelkshell Crystals and deliver them to Fanilly in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75363] = { id = 75363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepflayer Dust", description = "Why, I just got another letter from my good friend Mistie. She's been looking for interesting ingredient ideas for her smelly concoctions!\n\nA while ago, the kithguards took down a deepflayer near Loamm. I noticed a peculiar dust it shed when it perished. It had a unique aroma to it, and I'm sure Mistie would love to experiment with something like that!\n\nCould you gather some from the deepflayers near Loamm, then bring it to Miss Mistie? You'll be doing us a favor, too!", progress = "Such a mysterious musty aroma... the grim note of death alongside the gentleness of soil.", completion = "Oh yes, this'll do nicely! Can you smell that with your nose? It's very fragrant!", objectives = "Collect 10 Deepflayer Dust and deliver them to Mistie in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75364] = { id = 75364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emberdusk" }
quests[75365] = { id = 75365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75366] = { id = 75366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viridian King" }
quests[75367] = { id = 75367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obsidian Rest", description = "It is a miracle this outpost survived so long after Neltharion's... disappearance. \n\nFor weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory.\n\nWe must take every possible precaution and try to understand our enemy's motivations.", progress = "These are trying times for all of us.", completion = "We must discuss what you have learned, {name}.", objectives = "Gather information and resources at the Obsidian Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75368] = { id = 75368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones and Scales", description = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? \n\nThey're covered in both scales and stones! And have massive fangs!\n\nMister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", progress = "Have you collected those hides yet? Those snakes are a little scary, but I think a {class} like you can handle them!", completion = "Wonderful! These'll do nicely. Look how hard and sharp the scales are!\n\nThanks for your help, friend! I'll let Kayann know if I need anything else.", objectives = "Collect 10 Scaly Stone Hides from rock vipers  in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75369] = { id = 75369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Use Your Coin!", description = "Use that coin on the Warcraft  Rumble machine over there." }
quests[75370] = { id = 75370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smellincense" }
quests[75371] = { id = 75371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fascinating Fungi", description = "Ah, Uplander! Can I ask for your assistance?\n\nThe cavern below is full of mushrooms that are useful for all kinds of things! Miss Mistie has asked for help gathering them for her alchemical experiments.\n\nShe says the Gelcap mushrooms produce sticky spores that she can make into a balm, good for easing achy joints and bunions! I sure could use some after standing around on these hard stones all day!\n\nIf you can find her some, I'm sure she will make it worth your while!", progress = "Have you collected the spores? I'm eager to get my hands on them!", completion = "These are incredibly sticky spores! Thank you, {name}! \n\nNext time you see Kayann, tell him I'll get him his balm soon--and some free sunscreen to boot! I don't know how he stands being up there all day!", objectives = "Collect 10 Gelcap Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75372] = { id = 75372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive Them Before Us", description = "Drive these whelks from our lands, {name}!\n\nFor Imbu! For the Azure Span!", progress = "Glorious.", completion = "That'll leave a mark they won't soon forget!", objectives = "Slay djaradin and Primalists assaulting the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75373] = { id = 75373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge of the Ottuk Brigade", description = "Bah! They hide behind their barricades, hoping that will protect them from our vengeance.\n\nClear the way and we will ride them down like the cowards they are!", progress = "Soon we shall ride again, {name}.", completion = "Prepare to taste our spears, Fyrakk!", objectives = "Destroy djaradin barricades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75374] = { id = 75374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Defend the Span", description = "The djaradin struck without warning, {name}. Our people are capable fighters, but no one escapes a battle like this unscathed.\n\nPlease, help with the wounded. Many are trapped behind the enemy lines and can't make their way back in their current state.", progress = "There are always more wounded that need healing.", completion = "Fewer deaths is always worth celebrating. We have lost enough as it is.", objectives = "Heal 6 Gruff Fishers using the provided bandages or your own abilities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75375] = { id = 75375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Ice", description = "Whatever magic the djaradin are employing is lighting the ice on fire out there, {name}.\n\nWe can't let this spread to the wider Span. It has to be stopped before it consumes everything.\n\nGather as much water as you can while on that drake of yours and drown the fires. Hopefully that will be enough to extinguish them.", progress = "The sight of burning ice unnerves me.", completion = "Thank you, {name}. At least we can contain the damage.", objectives = "Extinguish fires across the djaradin camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75376] = { id = 75376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suffuse, Reuse, Recycle", description = "If Fyrakk is willing to openly attack the surface in pursuit of these materials, they must be vital to his plans.\n\nGrab whatever you can. There must be a way to turn these to our advantage.", progress = "We'll strengthen ourselves even as we deny our enemies.", completion = "Admirable work, {name}. They would not have let this go lightly.", objectives = "Recover infusion supplies from Fyrakk's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75377] = { id = 75377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining the Barricade", description = "It's all I can do to keep this shield up under the barrage these shadowflame drakes are putting out.\n\nThin their ranks before we're pinned down for good.", progress = "Incoming!", completion = "Excellent work. I might even be able to catch my breath before the next catastrophe.", objectives = "Slay or knock Primal Nightflames from the air with Whirling Surge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75378] = { id = 75378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Ambit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
