quests[75380] = { id = 75380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Ambit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75382] = { id = 75382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Combat", description = "The Primalists are channeling elemental forces through those portals, energizing their entire effort and speeding the production of these suffused ingots.\n\nSoon they will be stabilized enough to allow their elemental allies to pass through to reinforce their position.\n\nWe have to seal them before that happens or the battle may turn against us.\n\nTake this focus and disrupt the portals' protective runes, then we can strike from above. Only together do we stand a chance.", progress = "Together, {class}.", completion = "Excellent. That will at least stabilize the situation.", objectives = "Weaken the portals' defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75383] = { id = 75383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hideaway No More", description = "This was supposed to be a peaceful retirement, not a warzone!\n\nGrab one of those totems the shamans left lying around and put out these fires before my dreams of a nice fishing retreat go up in smoke! Literally!", progress = "Who burns down an ice fishing hut?", completion = "Good job, {race}. Maybe I'll get an afternoon to myself, yet.", objectives = "Use a water totem to extinguish fires in Grimtusk's Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75384] = { id = 75384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Payback's a Mammoth", description = "Trying to kill me I can forgive, but attacking my Hideaway? Now it's personal.\n\nThe djaradin are loading their mammoths with all the ingots they can bear to get them back to their precious Fyrakk.\n\nHijack one and bring it back here, cargo and all.", progress = "What are you waiting for? A thaw?", completion = "Now that's a statement!", objectives = "Mount an Overladen Mammoth and return it to your lines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75385] = { id = 75385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotar Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
