quests[75387] = { id = 75387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotar Tour - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75388] = { id = 75388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Vaults", description = "There's a problem in the Azure Vault, {name}. \n\nBeneath the Azure Archives rests the Azure Vault. Sindragosa stored many important and dangerous magical curiosities in it.\n\nA large group of Sundered Flame have broken into the vault to unlock its secrets.\n\nYou need to go in there and stop the Sundered Flame!", progress = "Take care within the vaults.", completion = "Thank you for your help within the vaults, {name}.", objectives = "Stop the Sundered Flame within the Azure Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75390] = { id = 75390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertical Anomaly" }
