quests[75397] = { id = 75397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Rascally Worms" }
quests[75398] = { id = 75398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Waking Shores flame.", objectives = "Honor the Midsummer Bonfire in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75407] = { id = 75407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silk Scavenging", description = "Hello friend! You're a tailor, right? So you must know about silk!\n\nMister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! \n\nYou should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!", progress = "Hey, uplander! Do you have those cocoons yet?", completion = "These look great! Thanks, {name}!\n\nNow we just need to boil them and turn them into thread. Oh they make SUCH a smelly smell when you boil them.\n\nWhat's that? You have to go? Oh, ok!", objectives = "Collect 10 Underlight Cocoons Fibers in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75408] = { id = 75408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling All Dracthyr!", description = "<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.>\n\nCalling all dracthyr!\n\nDo you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to?\n\nCome join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!", completion = "Everyone's tired, that much is clear. But this kind of togetherness is what will help us start healing.\n\nWhy don't you take a look around, talk to some {race}?", objectives = "Go to the party at Weyrnrest in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
