quests[75417] = { id = 75417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbol of Hope", description = "Champion--Ebyssian, Sabellian, and Wrathion have come to an agreement of who should lead, and are presenting a unified front. All three were quite eager to speak of your contributions and aid in Zaralek Cavern as well. It seems that they are also in agreement that they could not have succeeded without you.\n\nHigh praise indeed--and well deserved.\n\nPlease, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", progress = "Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", completion = "We still have much to do--but the sight of five united Aspects fills my heart with hope... and with joy. \n\nThank you. Your part in this will never be forgotten.", objectives = "Speak with Alexstrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75419] = { id = 75419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sundered Flames", description = "Did Neltharion keep this place as his hoard? No wonder that Sarkareth was looking for it. \n\nNeltharion's \"treasures\" litter every corner of it.\n\nThere's no telling what Sarkareth has gotten his claws on here.\n\nStay close!", completion = "I did not wish to fight Dezran. Sarkareth's strong personality and manipulative tongue are making his people follow his wildest whims.", objectives = "Find Sarkareth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
