quests[75440] = { id = 75440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satiating Sharpbeak", description = "Sheridon Hastle was our flight master and Sharpbeak's rider. After his death, she won't let anyone touch her.\n\n<Narvra clutches her side in pain.>\n\nOr feed her. Rupert tried but... she just won't.\n\nThe rest of us are too injured to move... I'm worried about her.\n\nCan you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent.\n\nAnd... if you can get her to accept food, she might let you ride her.", progress = "<Sharpbeak looks at you mournfully.>", completion = "<Sharpbeak tentatively accepts the feed from you. \n\nAfter a few snapping bites, she looks you in the eye, spreads her wings and shakes them.\n\nYou feel as though she might let you ride her if needed.>", objectives = "Feed Sharpbeak in the Dragonscale Camp in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75441] = { id = 75441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smelly Scramble" }
quests[75444] = { id = 75444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate Exploration: The Forbidden Reach", description = "<Another visit from Nanners, and another calling from the Dragonscale Expedition.\n\nIt seems Thaelin Darkanvil have something of an interest for you yet again.>", completion = "Good tae see ye again, {name}.\n\nThe Isles seem to be storin' endless opportunities fer adventure.", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
