quests[75456] = { id = 75456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News From Beneath", description = "Before I arrived, I was informed that the Life-Binder has need of our aid. There is news of the Incarnates, and she requests our presence at the Seat of the Aspects.\n\nAs for Emberthal -- there is very little we can do for now. It is best we allow her to reflect and gather thoughts alone.", completion = "The Aspects have gathered. Let us not keep them waiting.", objectives = "Meet Alexstrasza at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75459] = { id = 75459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brand New Digs" }
quests[75461] = { id = 75461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmaclaw Matriarch" }
quests[75462] = { id = 75462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouse Rescuers", description = "I feel bad for everything I did working for Malrogg. He was just so big and scary, I never felt like I had a choice...\n\n<Agrul slowly shakes his head.>\n\nNo more excuses. We need to get that sniffin' mouse back home to Yarren.\n\nI was never strong enough to take on Malrogg alone. But you... You can save Persii.", progress = "Did you find that drogbar?", completion = "I can't thank you both enough for saving Persii!", objectives = "Kill Malrogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
