quests[75466] = { id = 75466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Time-Lost Vikings", description = "Some rowdy customers stumbled out of a temporal portal a bit ago. Before I could get a Timewalker to help get them home, they decided to visit Valdrakken.\n\nWould you find Olaf, Baelog, and Eric and get them to come back here before they cause too much of a ruckus?", completion = "Those three had their fun, but it was high time they got back to their proper place.", objectives = "Convince the Lost Vikings to return to Eon's Fringe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
