quests[75493] = { id = 75493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Riverbed", description = "Hope you brought your boots, 'cause this is gonna be a wet one!\n\nThis river carries artifacts down from the mountains, and they wash up here in the silt. The centaur have found loads of stuff here over the years.\n\nWe're here to take a deeper look and see if there's anything interesting below the surface.", completion = "<Roska lets out a low whistle.>\n\nNow that's something you don't see every day. Let's get her out of there.", objectives = "Speak with Roska to start the dig, then excavate artifacts from the riverbed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75494] = { id = 75494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike the Colors" }
quests[75497] = { id = 75497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Catalyst's Boon", completion = "Every week, the catalyst will grant you enough power to imbue one piece of equipment.\n\nKeeper Tyr must be watching us. Wherever he is, this is no coincidence.", objectives = "Speak to Antuka in Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75498] = { id = 75498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
