quests[75505] = { id = 75505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75506] = { id = 75506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowflame Crests", description = "Now that you've gotten a taste of power, the real fun begins.\n\nFlightstones alone will only get you so far. We have also discovered four different tiers of Shadowflame Crests, which are required to empower ever more powerful gear.\n\nFifteen fragments can be combined to make a complete crest of its tier. Like Flightstones, fragments can be found across the Dragon Isles. The more dangerous the activity, the more powerful the fragments.\n\nAnd if you need fragments, visit Spinsoa outside. He can sell some.", progress = "Have you found enough fragments?", completion = "Perfection. Upgrade specialists will always identify if crests are needed for your upgrade.\n\nSpeaking of power, please take this trinket! I was told to distribute them to Loamm's newcomers as a welcome gift.\n\nWe can utilize the trinket in our next lesson.", objectives = "Visit Spinsoa and create a Shadowflame Crest by combining 15 Shadowflame Crest Fragments from the same tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75507] = { id = 75507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching Up with Friends", description = "Now that you've learned the fundamentals, you may have an easier time upgrading lower-level gear.\n\nWe can use the Friendship Censer trinket as an example. If you have acquired more powerful trinkets in the past, it will cost us less resources to upgrade this trinket.\n\nYou'll notice that fewer Flightstones will do the job! No crests required.\n\nGo ahead, try upgrading the trinket or a lower-level piece of equipment that you have. If you need another trinket, Innkeeper Floressa sells them.", progress = "You may wonder when you'd ever utilize this knowledge.\n\nWell, the Friendship Censer is much weaker than what I typically wear. But who doesn't want to be better friends with the niffen? I was able to quickly upgrade the trinket to my own gear's level. In fact, if I had more resources, I could fully achieve its potential to be even more powerful.", completion = "With this knowledge, I bless you to go forth and achieve the power you've always imagined. If you ever need a refresher, speak with me!", objectives = "Upgrade the Friendship Censer or an Explorer's level piece of equipment with Flightstones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75511] = { id = 75511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75516] = { id = 75516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Successful Interventions" }
quests[75517] = { id = 75517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak and Sniff" }
quests[75518] = { id = 75518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Body on the Banks", description = "<The state of the corpse of this centaur woman is surprising.\n\nHer clothing is in a style unfamiliar to you, and her skin is emblazoned with intricate tattoos.\n\nHer body is intact, so it seems as though she could not have been dead long... or could she? Conditions here may have led to better preservation.\n\nRoska will want to have a look at this!>", progress = "Nothing like silt, eh {name}? Never know what you'll find!", completion = "Would you look at that! I bet this poor gal has been buried under all that silt for hundreds of years if not more.\n\nBogs and riverbeds like this tend to preserve what's been left in them.\n\nBut now that she's out, we can find out more about who she was and how she got here!", objectives = "Speak to Roska to begin carefully excavating the centaur corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75519] = { id = 75519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Hunt", description = "<Dori'thur hovers silently, peering at you with keen, expectant eyes.\n\nWith a taloned foot, the noble owl offers you an imbued crystal. Within that crystal, you sense a message.>", completion = "<Dori'thur blinks knowingly.>", objectives = "Witness the message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75525] = { id = 75525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secured Shipment Looted" }
quests[75528] = { id = 75528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tester's Guide to Entering Zaralek", description = "Hail, and well met!\n\nWhile the story of Zaralek has yet to unfold, there is plenty to see within the cavern! Make way to Loamm, home of the Niffen.", sourceObjective = "Enter Zaralek Cavern through Iridikron's Gambit.", sourceObjectiveStatus = "unverified-source-field" }
quests[75538] = { id = 75538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", progress = "Everyone knows the way to the Faire...", completion = "You're... smaller, than I remember.", objectives = "Travel to the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75539] = { id = 75539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Wicked Things This Way Come", progress = "What have you learned, {name}?", completion = "Only one or two pairs of cold feet, hm? \n\n<Madam Shadow chuckles.>\n\nExcellent.\n\nNow that we know who wants to be here, it is time to determine who deserves to be here.", objectives = "Talk to the newly arrived warlocks around the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75540] = { id = 75540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hermetic Insurance", progress = "Is it done?", completion = "Delicious.", objectives = "Use Madam Shadow's Soulstone on willing initiates in the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75541] = { id = 75541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Hesitate", description = "Hm.\n\nThere is one who has been counted amongst our number, but is not here.\n\nThe draenei.\n\n<Madam Shadow inhales.>\n\nI can taste the Light about him. Go, see to it that he rejoins us.\n\nThere is much work to be done.", progress = "This view reminds me of... many things.", completion = "Now to appease our mysterious patron...", objectives = "Talk to Initiate Oman in the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75542] = { id = 75542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curses & Cultists", description = "The wheat has been separated from the chaff. Now the fun can truly begin.\n\nI have an exciting... field trip... planned for our students. But they are not yet ready. Take my grimoire and have the pandaren, zandalari, and tauren try their hand at curses. \n\nI found some uninvited guests loitering on the edges of our fairground. They should make excellent, if unwilling, test subjects.\n\nOman will have the honor of summoning the group far afield, and I will instruct him as such.", completion = "It worked! That grimoire of Madam Shadow's really is powerful...\n\nI hope I didn't startle you, {name}.", objectives = "Teach the initiates curses from Madam Shadow's grimoire in the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75543] = { id = 75543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Rites By Accident", description = "<You can hear the faint sound of screaming coming from the other side of the portal.>", completion = "The others... their soulstones...\n\nI saw a green flicker in their eyes as they fell, one by one. Like the very essence of their souls were being drawn forth.\n\nThey deserved better.", objectives = "Go through the Demonic Gateway and help the Initiates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75544] = { id = 75544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Revenge Burns Green", completion = "Those soulstones... the other warlocks. \n\n<Oman closes his green eyes.>\n\nWhen I chose to walk this path, I knew there would be repercussions. That I would be sacrificing a part of myself. A part of how my people see me. \n\nBut to have your soul torn asunder... for what? Petty revenge?\n\nTruly that is a fate worse than anything I have taken upon myself.", objectives = "Confront Madam Shadow in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75569] = { id = 75569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmith, Black Dragon", description = "The black dragonkin in the north of Zaralek Cavern are said to be fine blacksmiths.\n\nThey're quick to claim it has something do with a \"dominion over the earth\", but I'd like to see them try burrowing like a proper niffen!\n\nStill, you can't argue with the results. Grab a few examples and bring them to Kilnmaster Crubus in Loamm so he can study their techniques.", progress = "I wonder if I could use one of their helmets as a tub?", completion = "The craftsmanship is impeccable, but would it kill them to use a color besides black?", objectives = "Collect 8 Blackened Plate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75573] = { id = 75573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proclamation Reclamation", description = "You know who likes to hear themselves talk, loves bureaucracy, and enchants their own records? Dragons!\n\nGo poke around in the old black dragon fort north of Loamm. I'm sure they'll be all sort of magic-ish decrees, proclamations, and shopping lists just lying around!\n\nBring whatever you uncover to Scridorsa the Chiseler back in Loamm. I'm sure she'd love something new and heavily enchanted to read!", progress = "Can't do anything simply, can they?", completion = "<Scridorsa flips through the documents.>\n\n\"By my hand...\", \"The will of the Earth-Warder...\", \"At my command...\" Sounds like a dragon, sure enough!\n\nStill, these should make for an interesting study, if not read.", objectives = "Collect 10 Infused Proclamations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75575] = { id = 75575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ballistae Bits", description = "Those djaradin might smell like brutes, but their engineering corps must be top notch to keep churning out ballistae strong enough to threaten a dragon!\n\nNortheast of Loamm there's an ongoing scrap between them and some black dragons. There ought to be lots of spare parts scattered around. Or slightly used, moderately on fire ones, anyway!\n\nHaul them all back to Loamm! A little scorching won't stop our top minds from reverse niffeneering them.", progress = "I wonder what they use for torsion?", completion = "Interesting, that's a lot more bone than I would have expected given the stress involved!", objectives = "Collect 10 Ballistae Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75576] = { id = 75576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Guzzler Invasion!" }
quests[75598] = { id = 75598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailed It", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but lately I've come across my toughest case yet. Simply put, he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket, though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", completion = "I have never been prouder. Y'all snailed it.\n\nNot many have what it takes to enter the fast-paced world of snail racing, but you? You got it. I just know Slick is going to enjoy spending the rest of his snaily life going on adventures with you.\n\n<Briggul sniffles and pats Slick's shell.>\n\nHappy slime trails to you, big guy. Make sure you come back to visit!", objectives = "Introduce yourself to Slick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75600] = { id = 75600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silk's Silk", description = "We may not have access to all those fancy plant fibers you surface types use up here, but we do have a lot of options I bet you don't!\n\nThe spiders near Loamm make the most interesting smelling silk I ever did sniff. I think it might have something to do with their diet?\n\nIf you round some up, I'm sure Rossmar back in Loamm will be happy to teach you a thing or two about how to use it!", progress = "Just follow the bone-y smells!", completion = "Doesn't the calcium give it the best texture?", objectives = "Collect 8 Calcisilk Bundles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75602] = { id = 75602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chips off the Old Crystal Block", description = "The crystalline creatures back home are as mysterious as they are stompy.\n\nWhat allows them to move? Are they even really alive? What do they taste like?\n\nBring Fanilly a few samples to start studying. Just not any big enough to step on anyone in Loamm, ok?", progress = "Who knows what we could learn?", completion = "Fascinating, {name}, thank you for your contribution to the art.", objectives = "Collect 10 Living Chips.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75603] = { id = 75603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Rites by Her", description = "This gal has been here for a long, long time. It's a wonder she's in such good condition.\n\nIt's one thing to dig up pottery shards in the mud, but something like this requires more care and expertise than you and I have combined! Maruukai isn't far from here...\n\nWe should tell the centaur about this. They can decide how best they'd like to proceed, eh?\n\nWhile we're at it, I bet some of their expert artisans can tell us about her gear.", progress = "We've got a proper dig now here!", completion = "It doesn't get better than this, {name}. New chapters of history unfolding, whole communities rallying around a find... \n\nThey'll be talking about this dig for years!\n\nMakes all the stomping around in the mud worthwhile, doesn't it?", objectives = "Consult Storykeeper Jaru, Farrier Rondare, and Tigari Khan for guidance on how to treat the ancient corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75604] = { id = 75604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antiquated Antics", description = "Well, there's two factors at play here, eh?\n\nWe should do our due diligence and figure out who this was a statue of. But between you and me? I'm much more interested in learning about the jokesters that turned it into this work of art.\n\nI'm sure there's a historian of the black dragonflight somewhere near Aberrus. And why don't you poke around Loamm to see if there are any stories surrounding this kind of... artistic license.", progress = "<Roska looks pleased with your work.>", completion = "We'll keep up the dig around the tower. \n\nThere's still an awful lot of midden to go through. Even if we don't find something this spectacular again, we've got a lot to learn about the niffen and how they lived before and during the dragons leaving.\n\nBut I think we've done a good day's work for now!", objectives = "Find experts from both Loamm and the black dragonflight to weigh in on your find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75608] = { id = 75608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titan Trash or Titan Treasure?", description = "The watchers left all sorts of amazing technology just laying around when they went to sleep.\n\nWe could learn so much from their ancient castoffs. Even the least of contraptions are marvels to behold!\n\nIf only there was someone brave, intelligent, and dare I say handsome enough to go retrieve a few examples for our finest niffeneers back in Loamm to examine... sound familiar?", progress = "I wonder if we'll ever truly understand their technology?", completion = "What's a hololithic gear, you ask? I don't know, but I look forward to finding out!", objectives = "Collect 10 Hololithic Gears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75611] = { id = 75611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerfish Before It's Gone" }
quests[75612] = { id = 75612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cascades Calling" }
quests[75617] = { id = 75617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Ohn'ahran Plains flame.", objectives = "Honor the Midsummer Bonfire in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75619] = { id = 75619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Critters" }
quests[75620] = { id = 75620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liars in Light" }
quests[75621] = { id = 75621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Element Whispers" }
quests[75622] = { id = 75622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling All Competitors!", description = "The Artisan's Consortium has struck a deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can now purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this flier to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", completion = "Hm, they sure know how to reach their audience.\n\nHere are your trophies as promised. Use these when crafting your own equipment or submitting Crafting Orders and the gear will be comparable in power to what I offer. It is perfect if you are looking for something highly specific or imbued with a certain embellishment... and are willing to put in some extra work.\n\nQuestions? Take them to the Artisan's Market.", objectives = "Deliver the flier to Calderax in the Gladiator's Refuge of Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75624] = { id = 75624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Challenge" }
quests[75625] = { id = 75625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", completion = "Hey there, glad you could make it!\n\nYou gotta check out this machine!", objectives = "Speak with Mizzen at the Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75626] = { id = 75626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", completion = "Hey there, glad you could make it!\n\nYou gotta check out this machine!", objectives = "Speak with Mizzen in Orgrimmar's Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75632] = { id = 75632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dislocated Disc", description = "As a gesture of good will, Eternus has pledged her assistance in finding the disc that contains Tyr's memories. The infinites have devices that can aid in divining its location.\n\nTo quote Eternus, \"This is a mess Deios made. It is fair we help clean it up.\"\n\nI feel some responsibility as well after our attempt to wake Tyr with the Silver Scale.\n\nMeet Eternus at Tyrhold. She will brief you on her progress. Perhaps now our old friend will finally join us once more.", completion = "We meet again, {name}. Nozdormu said you would come. I welcome your aid.", objectives = "Meet Eternus in Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
